import {drawAll} from 'mod_imagemap/css_preview';
import Notification from 'core/notification';
import {getString} from 'core/str';

/**
 * Draw the previews and ask for confirmation before deleting an example.
 */
export const init = () => {
    drawAll(document);

    document.querySelectorAll('[data-action="mod_imagemap/delete-example"]').forEach((link) => {
        link.addEventListener('click', (event) => {
            event.preventDefault();
            Notification.saveCancelPromise(
                getString('delete', 'core'),
                getString('confirmdeleteexample', 'mod_imagemap'),
                getString('delete', 'core'),
            ).then(() => {
                window.location.href = link.href;
                return null;
            }).catch(() => null);
        });
    });
};
